-- ============================================================================
-- Bộ KPI của Huy Phong — nạp từ các file Excel đang dùng (Kho vận, Kế toán,
-- Marketing, Dự án, Nhập khẩu, Kinh doanh).
-- ----------------------------------------------------------------------------
-- Mỗi file là bộ KPI riêng của một người: bộ được gắn thẳng cho người đó nếu tìm
-- thấy đúng tên trong hồ sơ nhân sự; không thấy thì để là bộ mẫu, gán ở màn Bộ KPI.
-- Bộ Kinh doanh không ghi tên người — để là bộ mẫu, áp cho phòng ở màn Bộ KPI.
-- Bộ có tổng tỷ trọng khác 100% trong file gốc được nạp ở trạng thái chưa áp dụng.
-- Chạy lại an toàn: bộ đã có (cùng mã) thì bỏ qua.
-- ============================================================================

create or replace function pg_temp.fold(p text) returns text language sql immutable as $$
  select regexp_replace(translate(lower(normalize(coalesce(p, ''), NFC)),
    'àáảãạăằắẳẵặâầấẩẫậèéẻẽẹêềếểễệìíỉĩịòóỏõọôồốổỗộơờớởỡợùúủũụưừứửữựỳýỷỹỵđ',
    'aaaaaaaaaaaaaaaaaeeeeeeeeeeeiiiiiooooooooooooooooouuuuuuuuuuuyyyyyd'), '\s+', ' ', 'g');
$$;

