]$json$::jsonb;
  v_set jsonb;
  v_item jsonb;
  v_id uuid;
  v_user uuid;
  v_count integer;
  v_order integer;
begin
  for v_set in select * from jsonb_array_elements(v_sets) loop
    continue when exists (select 1 from public.kpi_sets where code = v_set ->> 'code');

    v_user := null;
    if v_set ->> 'person' is not null then
      select count(*), min(id::text)::uuid into v_count, v_user
      from public.profiles where is_active and pg_temp.fold(trim(name)) = pg_temp.fold(v_set ->> 'person');
      if v_count <> 1 and v_set ->> 'match' is not null then
        select count(*), min(id::text)::uuid into v_count, v_user
        from public.profiles
        where is_active and pg_temp.fold(trim(name)) ~ ('(^| )' || (v_set ->> 'match') || '$');
      end if;
      if v_count <> 1 then v_user := null; end if;
    end if;

    insert into public.kpi_sets (code, name, block, user_id, effective_from, is_active, board_review, note)
    values (
      v_set ->> 'code',
      v_set ->> 'name' || case when v_set ->> 'person' is not null and v_user is null
        then ' — ' || (v_set ->> 'person') else '' end,
      v_set ->> 'block', v_user, '2026-01-01', false, (v_set ->> 'board_review')::boolean,
      coalesce(v_set ->> 'note', 'Nạp từ bảng KPI Excel đang dùng.')
    )
    returning id into v_id;

    v_order := 0;
    for v_item in select * from jsonb_array_elements(v_set -> 'items') loop
      v_order := v_order + 1;
      insert into public.kpi_set_items (set_id, sort_order, category, name, measure, group_code, weight,
        standard_score, method, levels, ranges, value_unit, allow_over, source, note)
      values (v_id, v_order, v_item ->> 'category', v_item ->> 'name', v_item ->> 'measure', v_item ->> 'group_code',
        (v_item ->> 'weight')::numeric, (v_item ->> 'standard_score')::numeric, v_item ->> 'method',
        v_item -> 'levels', v_item -> 'ranges', v_item ->> 'value_unit', (v_item ->> 'allow_over')::boolean,
        v_item ->> 'source', v_item ->> 'note');
    end loop;

    if (v_set ->> 'is_active')::boolean then
      update public.kpi_sets set is_active = true where id = v_id;
    end if;
  end loop;
end;
$seed$;
